import java.util.Scanner;

public class P1047D {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        int m = scan.nextInt();
        System.out.println(solve(n, m));
    }

    private static long solve(long n, long m) {
        long min = Math.min(n, m);
        long max = Math.max(n, m);

        if (min == 1) {
            return max / 6 * 6 + 2 * Math.max(0, max % 6 - 3);
        }

        if (min == 2 && (max == 2 || max == 3 || max == 7)) {
            if (max == 2) return 0;
            if (max == 3) return 4;
            return 12;
        }

        if (min == 3 && max == 3) {
            return 8;
        }

        long ans = min * max;
        if ((max & 1L) == 1L) {
            ans -= ans % 2;
        }
        return ans;
    }
}
